sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    var defaults = {
        laptop: 'Required a laptop to carry out my daily work and project tasks.',
        monitor: 'Required an additional monitor to improve productivity and multitasking.',
        chair: 'Required an ergonomic chair for comfortable seating during long working hours.',
        mouse: 'Required a mouse as my current one is faulty or unavailable.',
        ups: 'Required a UPS to protect my equipment from power outages and surges.',
        keyboard: 'Required a keyboard as my current one is faulty or unavailable.'
    };

    var newText = defaults[String(newValue).toLowerCase()];
    if (!newText) {
        return;
    }

    // Only overwrite if the field is empty or still holds a default message
    var current = g_form.getValue('justification');
    var isDefault = false;
    for (var key in defaults) {
        if (defaults[key] === current) {
            isDefault = true;
            break;
        }
    }
    if (!current || isDefault) {
        g_form.setValue('justification', newText);
    }
}
